 "content": "def transform(grid):
    """Encode each 3x3 cell of the noisy grid by its nonzero, non-5 marker."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            markers = {grid[i][j] for i in range(r, min(r + 3, h))
                       for j in range(c, min(c + 3, w))
                       if grid[i][j] not in (0, 5)}
            row.append(next(iter(markers)) if markers else 0)
        out.append(row)
    return out
